// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { ChevronDownIcon, GlobeIcon, LockIcon, RefreshCwIcon, ShieldAlertIcon } from 'lucide-react'

import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  FIELDS,
  MISSING,
  READY,
  SECTIONS,
  SITE,
  URL_TEXT,
  explain,
  fillButton,
  type Field,
} from './script'

const PANEL = 276
const UNTICK = READY[READY.length - 1]
const FILLING = READY.filter((field) => field !== UNTICK)

const build: Build = ({ tl, q, qa, step, final, move, click, type, count, wait, cursorOut }) => {
  const scrollTo = (id: string, offset: number) => {
    const row = q(`row-${id}`)
    const view = q('list-view')
    const max = q('list').scrollHeight - view.clientHeight
    tl.to(q('list'), {
      y: -Math.min(max, Math.max(0, row.offsetTop - offset)),
      duration: 0.6,
      ease: 'power2.inOut',
    })
  }

  step(0)
  tl.to(q('scan'), { opacity: 1, duration: 0.2 }, 0.2)
  tl.to(
    qa('page-input'),
    { boxShadow: '0 0 0 2px rgba(59,130,246,0.35)', duration: 0.25, stagger: 0.05 },
    '<',
  )
  tl.to(qa('page-input'), { boxShadow: '0 0 0 0px rgba(59,130,246,0)', duration: 0.3 }, '+=0.1')
  tl.to(q('scan'), { opacity: 0, duration: 0.2 }, '<')
  tl.to(q('count'), { opacity: 1, duration: 0.2 }, '<')
  tl.fromTo(
    qa('row'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.3, stagger: 0.06, immediateRender: false },
    '<',
  )
  count('stat-ready', READY.length, { at: '<', duration: 0.5 })
  count('stat-missing', MISSING.length, { at: '<', duration: 0.5 })
  tl.set(q('fill-label'), { text: fillButton(READY.length) }, '<')
  move(`card-${READY[0].id}`, { at: '+=0.1', ax: 0.4 })
  wait(0.8)

  step(1, '+=0.2')
  scrollTo(UNTICK.id, 8)
  move(`chk-${UNTICK.id}`, { at: '<0.2' })
  click(`chk-${UNTICK.id}`)
  tl.to(q(`chk-on-${UNTICK.id}`), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q(`row-${UNTICK.id}`), { backgroundColor: 'rgba(255,255,255,0)', duration: 0.15 }, '<')
  tl.set(q('fill-label'), { text: fillButton(FILLING.length) }, '<')
  move('fill-btn')
  click('fill-btn')
  tl.set(q('fill-label'), { text: 'Filling…' }, '<')
  for (const field of FILLING) {
    type(`pf-${field.id}`, field.answer ?? '', { speed: 0.014 })
    tl.to(q(`state-${field.id}`), { opacity: 0, duration: 0.12 }, '<')
    tl.to(q(`done-${field.id}`), { opacity: 1, duration: 0.15 }, '<')
  }
  tl.to(q('fill-btn'), { opacity: 0, duration: 0.15 })
  tl.to(q('undo-row'), { opacity: 1, duration: 0.2 }, '<')
  scrollTo(FILLING[0].id, 0)
  wait(0.6)

  step(2, '+=0.2')
  scrollTo('password', 4)
  move('badge-password', { at: '<0.2' })
  tl.to(q('tip-password'), { opacity: 1, duration: 0.2 })
  tl.to(q('pg-password'), { boxShadow: '0 0 0 2px rgba(239,68,68,0.5)', duration: 0.25 }, '<')
  wait(1.1)
  tl.to(q('tip-password'), { opacity: 0, duration: 0.15 })
  move('badge-consent')
  tl.to(q('tip-consent'), { opacity: 1, duration: 0.2 })
  tl.to(q('pg-consent'), { boxShadow: '0 0 0 2px rgba(245,158,11,0.55)', duration: 0.25 }, '<')
  wait(1.2)
  cursorOut()
  final('+=0.2')
  wait(1.2)

  tl.set([q('scan'), q('count'), q('undo-row'), ...qa('done'), ...qa('tip')], { opacity: 0 }, 0)
  tl.set([q('fill-btn'), ...qa('state'), ...qa('chk-on')], { opacity: 1 }, 0)
  tl.set(q(`row-${UNTICK.id}`), { backgroundColor: 'rgba(52,211,153,0.06)' }, 0)
  tl.set(qa('page-input'), { boxShadow: '0 0 0 0px rgba(0,0,0,0)' }, 0)
  tl.set(q('list'), { y: 0 }, 0)
  tl.set(q('fill-label'), { text: fillButton(0) }, 0)
  tl.set(qa('pf'), { text: '' }, 0)
}

function StateBadge({ field }: { field: Field }) {
  if (field.protected) {
    return (
      <span className="relative">
        <span
          data-d="badge-password"
          className="flex items-center gap-0.5 rounded-full bg-red-500/15 px-1.5 py-px text-[7.5px] font-medium text-red-300"
        >
          <LockIcon className="size-2" /> Protected
        </span>
        <Tip d="tip-password" text={`Never read or filled: ${field.protected}`} />
      </span>
    )
  }
  if (field.consent) {
    return (
      <span className="relative">
        <span
          data-d="badge-consent"
          className="flex items-center gap-0.5 rounded-full bg-amber-500/15 px-1.5 py-px text-[7.5px] font-medium text-amber-300"
        >
          <ShieldAlertIcon className="size-2" /> Needs your OK
        </span>
        <Tip
          d="tip-consent"
          text="Terms, consent and declarations are never changed automatically."
        />
      </span>
    )
  }
  return (
    <span className="grid justify-items-end">
      <span
        data-d={`state state-${field.id}`}
        className={`[grid-area:1/1] rounded-full px-1.5 py-px text-[7.5px] font-medium ${field.state === 'matched' ? 'bg-emerald-500/15 text-emerald-300' : 'bg-white/[0.07] text-muted'}`}
      >
        {field.state === 'matched' ? 'Ready' : 'No answer'}
      </span>
      <span
        data-d={`done done-${field.id}`}
        className="[grid-area:1/1] rounded-full bg-sky-500/15 px-1.5 py-px text-[7.5px] font-medium text-sky-300 opacity-0"
      >
        Filled
      </span>
    </span>
  )
}

function Tip({ d, text }: { d: string; text: string }) {
  return (
    <span
      data-d={`tip ${d}`}
      className="absolute right-0 top-[calc(100%+4px)] z-10 w-36 rounded-md border border-line-strong bg-[#111116] px-2 py-1 text-[7.5px] leading-snug text-ink-soft opacity-0 shadow-xl"
    >
      {text}
    </span>
  )
}

function Row({ field }: { field: Field }) {
  const selectable = field.state === 'matched'
  return (
    <li
      data-d={`row row-${field.id}`}
      className={`flex items-start gap-2 border-b border-line px-2 py-1 last:border-b-0 ${selectable ? 'bg-emerald-400/[0.06]' : ''}`}
    >
      <span
        data-d={`chk-${field.id}`}
        className={`relative mt-px size-2.5 shrink-0 rounded-[3px] border ${field.state === 'missing' || selectable ? 'border-line-strong' : 'border-line opacity-40'}`}
      >
        {selectable ? (
          <span
            data-d={`chk-on chk-on-${field.id}`}
            className="absolute -inset-px flex items-center justify-center rounded-[3px] bg-[var(--accent)] text-[7px] leading-none text-canvas"
          >
            ✓
          </span>
        ) : null}
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-[9px] font-medium text-ink">
          {field.label}
          {field.required ? <span className="text-red-400"> *</span> : null}
        </span>
        <span className="block truncate text-[7.5px] text-muted">
          {field.type}
          {field.recognized ? ` · Recognized as ${field.recognized}` : ''}
        </span>
        {field.answer ? (
          <span
            data-d={`card-${field.id}`}
            className="mt-1 block rounded border-l-2 border-[var(--accent)]/50 bg-white/[0.04] px-1.5 py-0.5"
          >
            <span className="block truncate text-[8px] text-ink">
              <span className="font-medium">{field.answer}</span>
              <span className="text-muted"> · high confidence</span>
            </span>
            <span className="block truncate text-[7px] text-muted">{explain(field)}</span>
          </span>
        ) : null}
      </span>
      <StateBadge field={field} />
    </li>
  )
}

function Panel() {
  return (
    <div className="flex h-full flex-col" style={{ width: PANEL }}>
      <DockHeader />
      <div className="flex min-h-0 flex-1 flex-col gap-1.5 p-2">
        <div className="flex items-center gap-1.5 rounded-md border border-line px-2 py-1.5">
          <span className="flex size-5 shrink-0 items-center justify-center rounded bg-white/[0.06] text-ink-soft">
            <GlobeIcon className="size-3" />
          </span>
          <span className="min-w-0 flex-1">
            <span className="flex items-center gap-1">
              <span className="truncate text-[9px] font-medium text-ink">{SITE.title}</span>
              <span className="shrink-0 rounded-full bg-emerald-500/15 px-1 text-[7px] text-emerald-300">
                Connected
              </span>
            </span>
            <span className="block truncate text-[7.5px] text-muted">
              {SITE.host} · 1 frame · Portal: {SITE.portal}
            </span>
          </span>
          <RefreshCwIcon className="size-3 shrink-0 text-muted" />
        </div>
        <div className="grid grid-cols-5 gap-0.5 rounded-md bg-white/[0.04] p-0.5">
          {['Page', 'Answers', 'Profiles', 'Data', 'Settings'].map((label, index) => (
            <span
              key={label}
              className={`rounded py-0.5 text-center text-[8px] ${index === 0 ? 'bg-white/10 text-ink' : 'text-muted'}`}
            >
              {label}
            </span>
          ))}
        </div>
        <div className="flex items-center justify-between">
          <span className="text-[9.5px] font-semibold text-ink">Detected fields</span>
          <span className="relative text-[8px] text-muted">
            <span data-d="scan" className="absolute right-0 whitespace-nowrap opacity-0">
              Scanning…
            </span>
            <span data-d="count" className="opacity-0">
              {FIELDS.length} fields
            </span>
          </span>
        </div>
        <div className="grid grid-cols-3 gap-1">
          {[
            ['Ready', 'stat-ready', 'bg-emerald-400'],
            ['Review', 'stat-review', 'bg-amber-400'],
            ['Missing', 'stat-missing', 'bg-zinc-500'],
          ].map(([label, d, dot]) => (
            <span
              key={label}
              className="flex items-baseline gap-1 rounded-md border border-line px-1.5 py-0.5"
            >
              <span data-d={d} className="text-[10px] font-semibold tabular-nums text-ink">
                0
              </span>
              <span className="flex items-center gap-1 text-[7.5px] text-muted">
                <span className={`size-1.5 rounded-full ${dot}`} /> {label}
              </span>
            </span>
          ))}
        </div>
        <div data-d="list-view" className="relative min-h-0 flex-1 overflow-hidden">
          <div data-d="list" className="pb-12">
            {SECTIONS.map((section) => (
              <div key={section} className="mb-1.5">
                <p className="px-0.5 pb-0.5 text-[7.5px] font-semibold uppercase tracking-[0.12em] text-muted">
                  {section}
                </p>
                <ul className="rounded-md border border-line">
                  {FIELDS.filter((field) => field.section === section).map((field) => (
                    <Row key={field.id} field={field} />
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
        <div className="border-t border-line pt-1.5">
          <div className="flex items-center gap-1.5 text-[8px]">
            <span className="text-muted">Mode</span>
            <span className="flex items-center gap-0.5 rounded border border-line-strong px-1 text-ink">
              Review <ChevronDownIcon className="size-2" />
            </span>
            <span className="truncate text-muted">Fills only the fields you select.</span>
          </div>
          <div className="mt-1 grid">
            <span
              data-d="fill-btn"
              className="[grid-area:1/1] flex h-5 items-center justify-center rounded-md bg-[var(--accent)] text-[9px] font-medium text-canvas"
            >
              <span data-d="fill-label">{fillButton(0)}</span>
            </span>
            <span data-d="undo-row" className="[grid-area:1/1] flex items-center gap-1.5 opacity-0">
              <span className="flex h-5 flex-1 items-center justify-center rounded-md border border-line-strong text-[9px] text-ink">
                Undo fill
              </span>
              <span className="text-[7.5px] text-muted">Forms are never submitted.</span>
            </span>
          </div>
        </div>
      </div>
    </div>
  )
}

function Input({ id, label, required }: { id: string; label: string; required?: boolean }) {
  return (
    <span className="block min-w-0">
      <span className="block truncate text-[7px] font-medium text-[#334155]">
        {label}
        {required ? <span className="text-[#dc2626]"> *</span> : null}
      </span>
      <span
        data-d={`page-input pg-${id}`}
        className="mt-0.5 flex h-[17px] items-center rounded border border-[#cbd5e1] bg-white px-1.5 text-[8px] text-[#0f172a]"
      >
        <span data-d={`pf pf-${id}`} className="truncate" />
      </span>
    </span>
  )
}

function Page() {
  const label = (id: string) => FIELDS.find((field) => field.id === id) as Field
  const input = (id: string) => (
    <Input id={id} label={label(id).label} required={label(id).required} />
  )
  return (
    <div className="h-full bg-[#f8fafc] px-3 pt-3 text-[#0f172a]">
      <p className="text-[7px] font-semibold uppercase tracking-[0.18em] text-[#16a34a]">
        Northwind · Careers
      </p>
      <h3 className="mt-0.5 text-[12px] font-bold leading-tight">Product Designer</h3>
      <p className="text-[7.5px] text-[#64748b]">Remote · Full-time</p>
      <p className="mt-2 text-[8.5px] font-semibold">Apply for this job</p>
      <div className="mt-1.5 grid grid-cols-2 gap-x-2 gap-y-1.5">
        {input('first')}
        {input('last')}
        <span className="col-span-2">{input('email')}</span>
        {input('phone')}
        {input('linkedin')}
        <span className="col-span-2">{input('heard')}</span>
        <span className="col-span-2">{input('password')}</span>
      </div>
      <span className="mt-2 flex items-center gap-1.5 text-[7.5px] text-[#334155]">
        <span
          data-d="page-input pg-consent"
          className="size-2.5 shrink-0 rounded-sm border border-[#94a3b8] bg-white"
        />
        {label('consent').label}
        <span className="text-[#dc2626]">*</span>
      </span>
      <span className="mt-2.5 flex h-6 w-24 items-center justify-center rounded-md bg-[#16a34a] text-[8.5px] font-semibold text-white">
        Submit application
      </span>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Form autofill reading a ${SITE.portal} job application, matching ${READY.length} fields to saved answers, filling ${FILLING.length} after one is unticked, and leaving the password and consent box alone`}
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome url={URL_TEXT} panelWidth={PANEL} panel={<Panel />}>
        <Page />
      </BrowserChrome>
    </DemoStage>
  )
}
